import{_ as a,o,c as l,a2 as t}from"./chunks/framework.BXA5Pi9t.js";const m=JSON.parse('{"title":"Ceph Developer Monthly 2024-02-07","description":"","frontmatter":{"title":"Ceph Developer Monthly 2024-02-07","date":"2024-02-07T00:00:00.000Z","updated":"2024-02-14T00:00:00.000Z","tags":["Ceph","DevOps","分布式存储","NVMe","oF","高可用性"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2024/Ceph_Developer_Monthly_2024-02-07.md","filePath":"posts/2024/Ceph_Developer_Monthly_2024-02-07.md","lastUpdated":1780460162000}'),i={name:"posts/2024/Ceph_Developer_Monthly_2024-02-07.md"};function r(n,e,s,h,p,d){return o(),l("div",null,[...e[0]||(e[0]=[t('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="会议主题-s-dev-月度会议" tabindex="-1">会议主题：S Dev 月度会议 <a class="header-anchor" href="#会议主题-s-dev-月度会议" aria-label="Permalink to &quot;会议主题：S Dev 月度会议&quot;">​</a></h4><h4 id="日期-2024年2月7日" tabindex="-1">日期：2024年2月7日 <a class="header-anchor" href="#日期-2024年2月7日" aria-label="Permalink to &quot;日期：2024年2月7日&quot;">​</a></h4><h4 id="参会人员-pon、yal等ceph开发者" tabindex="-1">参会人员：Pon、Yal等Ceph开发者 <a class="header-anchor" href="#参会人员-pon、yal等ceph开发者" aria-label="Permalink to &quot;参会人员：Pon、Yal等Ceph开发者&quot;">​</a></h4><h4 id="会议议程" tabindex="-1">会议议程： <a class="header-anchor" href="#会议议程" aria-label="Permalink to &quot;会议议程：&quot;">​</a></h4><ol><li><strong>PR审查请求</strong> - Pon的PR，关于monit monitor manager不输出Network ping stats。</li><li><strong>NVMe TCP Gateway</strong> - 介绍NVMe-oF的基本概念和其在Ceph中的应用，以及高可用性解决方案。</li><li><strong>PR审查请求</strong> - Pon的PR，关于monit monitor manager不输出Network ping stats的后续讨论。</li><li><strong>端到端追踪</strong> - Yal的PR，关于端到端追踪功能的实现和测试。</li></ol><h4 id="讨论内容" tabindex="-1">讨论内容： <a class="header-anchor" href="#讨论内容" aria-label="Permalink to &quot;讨论内容：&quot;">​</a></h4><ol><li><p><strong>PR审查请求 - monit monitor manager不输出Network ping stats</strong></p><ul><li>Pon提出了一个PR，请求审查关于monit monitor manager不输出Network ping stats的改动。</li><li>讨论了该PR的动机和潜在影响，特别是对现有脚本和API的兼容性问题。</li><li>决定在下一个主要版本中进行此改动，并更新发布说明。</li></ul></li><li><p><strong>NVMe TCP Gateway</strong></p><ul><li>介绍了NVMe-oF的基本概念和其在Ceph中的应用。</li><li>讨论了NVMe-oF的高可用性解决方案，包括Gateway Group和自动故障转移机制。</li><li>展示了如何在Ceph中实现NVMe-oF的高可用性，并讨论了未来的发展方向。</li></ul></li><li><p><strong>PR审查请求 - monit monitor manager不输出Network ping stats（后续讨论）</strong></p><ul><li>进一步讨论了该PR的影响和是否需要添加配置选项以保留网络ping统计信息。</li><li>决定先解决主要问题，后续再考虑添加配置选项。</li></ul></li><li><p><strong>端到端追踪</strong></p><ul><li>Yal介绍了端到端追踪功能的PR，并请求帮助审查测试结果。</li><li>讨论了该功能的测试情况和未来的推广计划。</li><li>决定将此功能作为Squid版本的阻塞项，并确保测试结果的审查。</li></ul></li></ol><h4 id="决定事项" tabindex="-1">决定事项： <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项：&quot;">​</a></h4><ul><li>批准Pon的PR，关于monit monitor manager不输出Network ping stats的改动，并更新发布说明。</li><li>确认NVMe-oF的高可用性解决方案，并计划在未来版本中实现生产就绪。</li><li>将端到端追踪功能作为Squid版本的阻塞项，并确保测试结果的审查。</li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划： <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划：&quot;">​</a></h4><ul><li>Pon将发送邮件通知社区关于monit monitor manager改动的情况。</li><li>Yal将更新PR，添加性能测试结果的链接，并确保测试结果的审查。</li><li>继续推进NVMe-oF的高可用性解决方案的开发和测试。</li></ul><h4 id="会议总结" tabindex="-1">会议总结： <a class="header-anchor" href="#会议总结" aria-label="Permalink to &quot;会议总结：&quot;">​</a></h4><p>本次会议讨论了多个关键的技术议题，包括NVMe-oF的高可用性解决方案和端到端追踪功能的实现。通过详细的讨论和审查，确定了各个议题的后续行动计划，并确保了技术决策的透明性和社区的参与度。</p>',14)])])}const P=a(i,[["render",r]]);export{m as __pageData,P as default};
